1	// How a scenario unfolds. This module knows the order events happen in and
2	// what each step leaves behind for the next one; it delegates what a policy
3	// costs to pricing.ts and what it pays out to coverage.ts.
4	
5	import { premiumFor, type Customer, type Item } from "./pricing.js";
6	import {
7	  capFor,
8	  payoutForDamages,
9	  settleClaim,
10	  type Damage,
11	} from "./coverage.js";
12	import { claimRejection } from "./rejection.js";
13	
14	export type { Customer, KnownItemType } from "./pricing.js";
15	export type { Damage } from "./coverage.js";
16	
17	export interface Scenario {
18	  customer: Customer;
19	  steps: Step[];
20	}
21	
22	export interface QuoteStep {
23	  op: "quote";
24	  items: Item[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: { cause: string; damages: Damage[] };
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface ScenarioResults {
36	  results: ({ premium: number } | { payout: number; remainingCap: number })[];
37	}
38	
39	// What earlier steps have established by the time a later step is priced.
40	// Steps are not independent: a quote is a follow-up contract when the customer
41	// already took a quote earlier in the same scenario. Folding this forward —
42	// rather than re-deriving it from the step prefix — is what lets a step read
43	// the state its predecessors left behind.
44	// Named for the live coverage a policy has left, not for the policy itself.
45	// This record is NOT the contract: it carries no premium, no customer, no
46	// policy context — and its remainingCap is rewritten by every claim settled
47	// against it. Calling it `Policy` made the mutation read as if the contract
48	// itself were changing, and collided with ClaimStep.policy, which holds a step
49	// INDEX rather than any of this. That collision is the tell: runClaim had to
50	// rename the field locally to stay readable.
51	interface PolicyCoverage {
52	  // The insured items, kept because a claim is settled against them: what a
53	  // damage reimburses depends on the item's own material and enchantment, not
54	  // on the damage entry alone.
55	  items: Item[];
56	  remainingCap: number;
57	}
58	
59	interface ScenarioState {
60	  hasQuoted: boolean;
61	  // Keyed by the step index of the quote that created the policy, which is
62	  // how a later claim step refers to it.
63	  coverages: Map<number, PolicyCoverage>;
64	}
65	
66	const INITIAL_STATE: ScenarioState = { hasQuoted: false, coverages: new Map() };
67	
68	type StepOutcome = ScenarioResults["results"][number];
69	
70	interface StepRun {
71	  outcome: StepOutcome;
72	  state: ScenarioState;
73	}
74	
75	// Every coverage a step establishes or revises is recorded the same way, so
76	// both handlers go through here rather than each rebuilding the map.
77	const withCoverage = (
78	  state: ScenarioState,
79	  index: number,
80	  coverage: PolicyCoverage,
81	): ScenarioState => ({
82	  ...state,
83	  coverages: new Map(state.coverages).set(index, coverage),
84	});
85	
86	const runQuote = (
87	  { items }: QuoteStep,
88	  customer: Customer,
89	  state: ScenarioState,
90	  index: number,
91	): StepRun => ({
92	  outcome: {
93	    premium: premiumFor(items, {
94	      customer,
95	      isFollowUpContract: state.hasQuoted,
96	    }),
97	  },
98	  state: withCoverage({ ...state, hasQuoted: true }, index, {
99	    items,
100	    remainingCap: capFor(items),
101	  }),
102	});
103	
104	const runClaim = (
105	  { policy: policyIndex, incident }: ClaimStep,
106	  state: ScenarioState,
107	): StepRun => {
108	  // A claim always names a policy an earlier quote step created. No spec
109	  // example covers a claim naming a step that never quoted, so this is not the
110	  // considered answer to that question — but the previous fallback of an empty
111	  // policy was worse than none: it returned a payout of 0 with 0 cap left,
112	  // which is indistinguishable from a real policy that has exhausted its cap.
113	  // A typo'd index read as a legitimate settlement. Fail loudly instead until
114	  // an example says otherwise.
115	  const coverage = state.coverages.get(policyIndex);
116	  if (coverage === undefined) {
117	    throw claimRejection(`names policy ${policyIndex}, which no step created`);
118	  }
119	  const { payout, remainingCap } = settleClaim(
120	    payoutForDamages(coverage.items, incident.damages),
121	    coverage.remainingCap,
122	  );
123	
124	  return {
125	    outcome: { payout, remainingCap },
126	    state: withCoverage(state, policyIndex, { ...coverage, remainingCap }),
127	  };
128	};
129	
130	// Dispatches a step to its handler. Written as an exhaustive switch on `op`
131	// so that adding a step kind to the Step union turns "I forgot to handle it"
132	// into a compile error rather than a wrong number.
133	const runStep = (
134	  step: Step,
135	  customer: Customer,
136	  state: ScenarioState,
137	  index: number,
138	): StepRun => {
139	  switch (step.op) {
140	    case "quote":
141	      return runQuote(step, customer, state, index);
142	    case "claim":
143	      return runClaim(step, state);
144	  }
145	};
146	
147	export const runScenario = ({ customer, steps }: Scenario): ScenarioResults => {
148	  const { results } = steps.reduce<{
149	    results: StepOutcome[];
150	    state: ScenarioState;
151	  }>(
152	    ({ results, state }, step, index) => {
153	      const stepRun = runStep(step, customer, state, index);
154	      return { results: [...results, stepRun.outcome], state: stepRun.state };
155	    },
156	    { results: [], state: INITIAL_STATE },
157	  );
158	
159	  return { results };
160	};
161

1	// What a policy costs. This module answers one question — given the items on
2	// a policy and the context the policy is written in, what premium does the
3	// customer pay? It knows nothing about scenarios, steps, or the order events
4	// happen in; see claim-office.ts for that. What a policy pays OUT is the
5	// mirror question, answered by coverage.ts.
6	
7	import { roundUpInFavourOfMHPCO } from "./rounding.js";
8	import { quoteRejection } from "./rejection.js";
9	
10	export interface Customer {
11	  yearsWithMHPCO: number;
12	}
13	
14	const PROCESSING_FEE = 5;
15	const BASE_PREMIUM_BY_TYPE = {
16	  sword: 100,
17	  amulet: 60,
18	  staff: 80,
19	  potion: 40,
20	  rune: 25,
21	  moonstone: 25,
22	} as const satisfies Record<string, number>;
23	
24	export type KnownItemType = keyof typeof BASE_PREMIUM_BY_TYPE;
25	
26	export interface Item {
27	  type: KnownItemType;
28	  material?: string;
29	  enchantment?: number;
30	  cursed?: boolean;
31	}
32	
33	const FIRST_INSURANCE_SURCHARGE = 0.1;
34	
35	// The MHPCO's price list is closed: an item whose type is absent from it has
36	// no premium and no insurance value, so the quote is refused rather than
37	// guessed at. The type reaches here from parsed JSON, so the compiler's
38	// KnownItemType narrowing is not enough on its own.
39	const basePremiumOf = (item: Item): number => {
40	  const basePremium: number | undefined = BASE_PREMIUM_BY_TYPE[item.type];
41	  if (basePremium === undefined) {
42	    throw quoteRejection(
43	      `names a ${item.type}, which the MHPCO does not insure`,
44	    );
45	  }
46	  return basePremium;
47	};
48	
49	const BLOCK_SIZE = 3;
50	const BLOCK_BASE_PREMIUM = 60;
51	
52	const groupByType = (items: Item[]): Item[][] => [
53	  ...items
54	    .reduce(
55	      (groups, item) =>
56	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
57	      new Map<KnownItemType, Item[]>(),
58	    )
59	    .values(),
60	];
61	
62	const sumOfBasePremiums = (items: Item[]): number =>
63	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
64	
65	// Exactly three alike components form a block at a reduced premium; any
66	// other count is priced per item.
67	//
68	// Deliberate simplification: "component" is not yet enforced, so three alike
69	// swords would also get the block. No test covers it and the spec gives no
70	// example — revisit when one does.
71	const groupBasePremiumOf = (group: Item[]): number =>
72	  group.length === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : sumOfBasePremiums(group);
73	
74	const policyBasePremiumOf = (items: Item[]): number =>
75	  groupByType(items).reduce((sum, group) => sum + groupBasePremiumOf(group), 0);
76	
77	const CURSE_SURCHARGE = 0.5;
78	
79	// Item-specific modifiers are charged as a percentage of the affected item's
80	// OWN base premium. See withPolicyWideModifiers for the other scope.
81	const shareOfOwnBasePremium = (item: Item, rate: number): number =>
82	  basePremiumOf(item) * rate;
83	
84	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
85	const HIGH_ENCHANTMENT_THRESHOLD = 5;
86	
87	const isHighlyEnchanted = (item: Item): boolean =>
88	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
89	
90	const ITEM_SURCHARGES: { applies: (item: Item) => boolean; rate: number }[] = [
91	  { applies: (item) => item.cursed === true, rate: CURSE_SURCHARGE },
92	  { applies: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE },
93	];
94	
95	// Every modifier rate in this domain combines additively, whether item-scoped
96	// or policy-wide: two rates of +50 % and +30 % make +80 %, never +95 %.
97	const combinedRate = (rates: number[]): number =>
98	  rates.reduce((total, rate) => total + rate, 0);
99	
100	// Both item modifiers can apply at once, and they stack additively: a cursed
101	// item with enchantment 5 pays 50 % + 30 % of its base premium.
102	const surchargeRateOn = (item: Item): number =>
103	  combinedRate(
104	    ITEM_SURCHARGES.filter(({ applies }) => applies(item)).map(
105	      ({ rate }) => rate,
106	    ),
107	  );
108	
109	const surchargeOn = (item: Item): number =>
110	  shareOfOwnBasePremium(item, surchargeRateOn(item));
111	
112	const itemSurchargesOf = (items: Item[]): number =>
113	  items.reduce((sum, item) => sum + surchargeOn(item), 0);
114	
115	// Policy-wide modifiers scale the whole policy base premium, unlike item
116	// modifiers which are charged against the affected item's own base premium.
117	// They combine additively, so a policy carrying +10 % and -20 % pays 90 % of
118	// its base — not 110 % × 80 %.
119	const LOYALTY_DISCOUNT = -0.2;
120	const LOYALTY_THRESHOLD_YEARS = 2;
121	
122	const isLoyal = (customer: Customer): boolean =>
123	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
124	
125	const FOLLOW_UP_CONTRACT_DISCOUNT = -0.15;
126	
127	// Everything about the policy's context that shifts its rates, as opposed to
128	// the items being priced. Travels as one value because every policy-wide
129	// modifier reads from it.
130	export interface PolicyContext {
131	  customer: Customer;
132	  isFollowUpContract: boolean;
133	}
134	
135	const policyWideModifierRatesFor = ({
136	  customer,
137	  isFollowUpContract,
138	}: PolicyContext): number[] => [
139	  FIRST_INSURANCE_SURCHARGE,
140	  ...(isLoyal(customer) ? [LOYALTY_DISCOUNT] : []),
141	  ...(isFollowUpContract ? [FOLLOW_UP_CONTRACT_DISCOUNT] : []),
142	];
143	
144	const withPolicyWideModifiers = (
145	  policyBase: number,
146	  policy: PolicyContext,
147	): number =>
148	  policyBase * (1 + combinedRate(policyWideModifierRatesFor(policy)));
149	
150	export const premiumFor = (items: Item[], policy: PolicyContext): number =>
151	  roundUpInFavourOfMHPCO(
152	    withPolicyWideModifiers(policyBasePremiumOf(items), policy) +
153	      itemSurchargesOf(items) +
154	      PROCESSING_FEE,
155	  );
